package com.aistock.prediction.modelcatalog;
import com.aistock.prediction.forecast.*;import com.aistock.prediction.verification.*;import com.aistock.prediction.marketuse.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@Tag("mysql") class ForecastMarketUseMysqlTest {
 @Test void fiveDayForecastUsesBoundRawAndProofFollowsActualCommit(){var s=new ForecastMysqlTest.Setup();var clock=Clock.fixed(ForecastMysqlTest.NOW,ZoneOffset.UTC);var c=mock(MarketUseClient.class);var raw=ForecastMysqlTest.window().path("rawVersionId").asText();var b=new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(raw));when(c.register(any())).thenReturn(b);when(c.complete(any(),any())).thenReturn(new MarketUseClient.Receipt(b.bundleId(),"RELEASED",b.versionIds()));var owner=new PredictionMarketUseOwner(s.f.jdbc,ForecastMysqlTest.M,s.records,new VerificationRepository(s.f.jdbc,ForecastMysqlTest.M,clock),c,clock,true,true);var calls=new java.util.concurrent.atomic.AtomicInteger();var deps=new ForecastDependencies(){public com.fasterxml.jackson.databind.JsonNode prepare(String stock,UUID op){assertEquals(op.toString(),MarketUseContext.headers().get("X-Market-Use-Operation"));assertEquals("FORECAST",MarketUseContext.headers().get("X-Market-Use-Purpose"));return ForecastMysqlTest.window();}public com.fasterxml.jackson.databind.JsonNode infer(ModelRecords.Version model,com.fasterxml.jackson.databind.JsonNode w){calls.incrementAndGet();return ForecastMysqlTest.result(model,w);}};var svc=new ForecastService(s.records,s.models,deps,ForecastMysqlTest.M,clock,owner);var input=s.input();var r=svc.create(ForecastMysqlTest.USER,input);assertEquals("SUCCEEDED",r.state());assertEquals(5,r.snapshot().path("prediction").path("points").size());assertEquals(r.predictionId().toString(),owner.proof("FORECAST",r.predictionId(),"1").path("resultIdentity").asText());assertTrue(s.f.jdbc.queryForObject("select completion_acked from prediction_market_use",Boolean.class));assertEquals(r,svc.create(ForecastMysqlTest.USER,input));assertEquals(1,calls.get());assertTrue(MarketUseContext.headers().isEmpty());}
 @Test void wrongRawStopsBeforeInferenceAndWrongGenerationCannotSave(){var s=new ForecastMysqlTest.Setup();var clock=Clock.fixed(ForecastMysqlTest.NOW,ZoneOffset.UTC);var c=mock(MarketUseClient.class);when(c.register(any())).thenReturn(new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(UUID.randomUUID().toString())));var owner=new PredictionMarketUseOwner(s.f.jdbc,ForecastMysqlTest.M,s.records,new VerificationRepository(s.f.jdbc,ForecastMysqlTest.M,clock),c,clock,true,true);var deps=mock(ForecastDependencies.class);when(deps.prepare(anyString(),any())).thenReturn(ForecastMysqlTest.window());var svc=new ForecastService(s.records,s.models,deps,ForecastMysqlTest.M,clock,owner);var r=svc.create(ForecastMysqlTest.USER,s.input());assertEquals("FAILED",r.state());verify(deps,never()).infer(any(),any());assertNull(r.snapshot());assertThrows(com.aistock.common.BusinessException.class,()->s.records.succeed(ForecastMysqlTest.USER,r.predictionId(),2,ForecastMysqlTest.window()));assertEquals("FAILED",owner.proof("FORECAST",r.predictionId(),"1").path("state").asText());}
 @Test void permissionRefusalDoesNotReadOrInfer(){var s=new ForecastMysqlTest.Setup();var clock=Clock.fixed(ForecastMysqlTest.NOW,ZoneOffset.UTC);var c=mock(MarketUseClient.class);doThrow(MarketUseClient.notReady()).when(c).requireReady();var owner=new PredictionMarketUseOwner(s.f.jdbc,ForecastMysqlTest.M,s.records,new VerificationRepository(s.f.jdbc,ForecastMysqlTest.M,clock),c,clock,true,true);var deps=mock(ForecastDependencies.class);var r=new ForecastService(s.records,s.models,deps,ForecastMysqlTest.M,clock,owner).create(ForecastMysqlTest.USER,s.input());assertEquals("FAILED",r.state());verifyNoInteractions(deps);verify(c,never()).register(any());}

 @Test void expiredForecastProofIsDurablyFailedAndRejectsLateSuccess(){var s=new ForecastMysqlTest.Setup();var clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return s.time.get();}};var c=mock(MarketUseClient.class);var b=new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(ForecastMysqlTest.window().path("rawVersionId").asText()));when(c.register(any())).thenReturn(b);var owner=new PredictionMarketUseOwner(s.f.jdbc,ForecastMysqlTest.M,s.records,new VerificationRepository(s.f.jdbc,ForecastMysqlTest.M,clock),c,clock,true,true);var claim=s.records.claim(ForecastMysqlTest.USER,s.input(),"fixture",()->s.model);var id=claim.record().predictionId();try(var scope=owner.acquire("FORECAST",id,1)){}assertThrows(com.aistock.common.BusinessException.class,()->owner.proof("FORECAST",id,"1"));s.time.set(ForecastMysqlTest.NOW.plusSeconds(181));var proof=owner.proof("FORECAST",id,"1");assertEquals("FAILED",proof.path("state").asText());assertEquals("FAILED",s.records.get(ForecastMysqlTest.USER,id).state());assertFalse(s.records.succeed(ForecastMysqlTest.USER,id,1,ForecastMysqlTest.window()));assertEquals(proof,new PredictionMarketUseOwner(s.f.jdbc,ForecastMysqlTest.M,s.records,new VerificationRepository(s.f.jdbc,ForecastMysqlTest.M,clock),c,clock,false,false).proof("FORECAST",id,"1"));assertEquals(2,proof.path("fencingRevision").asLong());}
 @Test void unknownForecastRegistrationRecoversOriginalRequestWithoutComputing(){var s=new ForecastMysqlTest.Setup();var clock=Clock.fixed(ForecastMysqlTest.NOW,ZoneOffset.UTC);var c=mock(MarketUseClient.class);when(c.register(any())).thenThrow(MarketUseClient.unavailable());var owner=new PredictionMarketUseOwner(s.f.jdbc,ForecastMysqlTest.M,s.records,new VerificationRepository(s.f.jdbc,ForecastMysqlTest.M,clock),c,clock,true,true);var deps=mock(ForecastDependencies.class);var result=new ForecastService(s.records,s.models,deps,ForecastMysqlTest.M,clock,owner).create(ForecastMysqlTest.USER,s.input());assertEquals("FAILED",result.state());var captured=org.mockito.ArgumentCaptor.forClass(MarketUseClient.Request.class);verify(c).register(captured.capture());var request=captured.getValue();assertEquals(result.predictionId().toString(),request.operationId());var b=new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(ForecastMysqlTest.window().path("rawVersionId").asText()));when(c.find(request)).thenReturn(Optional.of(b));when(c.complete(request,b)).thenReturn(new MarketUseClient.Receipt(b.bundleId(),"RELEASED",b.versionIds()));new PredictionMarketUseOwner(s.f.jdbc,ForecastMysqlTest.M,s.records,new VerificationRepository(s.f.jdbc,ForecastMysqlTest.M,clock),c,clock,true,true).recoverOne("FORECAST",result.predictionId(),1);verify(c,times(1)).register(any());verify(c).find(request);verifyNoInteractions(deps);assertTrue(s.f.jdbc.queryForObject("select completion_acked from prediction_market_use",Boolean.class));}
 @Test void expiredForecastGrantDoesNotStartInputPreparation(){
  var s=new ForecastMysqlTest.Setup();
  var clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return s.time.get();}};
  var c=mock(MarketUseClient.class);
  var b=new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(ForecastMysqlTest.window().path("rawVersionId").asText()));
  when(c.register(any())).thenAnswer(call->{s.time.set(ForecastMysqlTest.NOW.plusSeconds(181));return b;});
  when(c.complete(any(),eq(b))).thenReturn(new MarketUseClient.Receipt(b.bundleId(),"RELEASED",b.versionIds()));
  var owner=new PredictionMarketUseOwner(s.f.jdbc,ForecastMysqlTest.M,s.records,new VerificationRepository(s.f.jdbc,ForecastMysqlTest.M,clock),c,clock,true,true);
  var deps=mock(ForecastDependencies.class);
  var done=new ForecastService(s.records,s.models,deps,ForecastMysqlTest.M,clock,owner).create(ForecastMysqlTest.USER,s.input());
  verifyNoInteractions(deps);
  assertEquals("FAILED",done.state());
  verify(c).complete(any(),eq(b));
 }

}
